import merge from 'lodash-es/merge.js';
import defaultConfigs from './utils/configs.js';
export * from './enums.js';
export * from './types.js';
export default class AlgoStack {
    constructor(configs = {}, modules = {}) {
        this.configs = merge(defaultConfigs, configs);
        // Add modules
        if (modules.cache)
            this.cache = modules.cache;
        if (modules.nfds)
            this.nfds = modules.nfds.init(this);
        if (modules.client)
            this.client = modules.client.init(this);
        if (modules.txns)
            this.txns = modules.txns.init(this);
        if (modules.files)
            this.files = modules.files.init(this);
        if (modules.medias)
            this.medias = modules.medias.init(this);
        if (modules.query) {
            this.query = modules.query.init(this);
            this.lookup = this.query.lookup;
            this.search = this.query.search;
        }
        // init cache after every other modules
        if (this.cache)
            this.cache.init(this);
    }
    setConfigs(configs) {
        if (configs.global)
            this.configs = merge(defaultConfigs, configs.global);
        Object.entries(configs)
            .forEach(([module, configs]) => {
            if (this[module])
                this[module].setConfigs(configs);
        });
    }
}
